<body>
<header><div class="bar"><span class="logo" aria-hidden="true"><svg width="23" height="23" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><rect x="4" y="3" width="16" height="16" rx="3"/><path d="M4 12h16M12 4v8M7 19v3m10-3v3M7 16h2m6 0h2"/></svg></span><span class="brand">Stop Ledger</span><span class="offline">Offline workspace</span></div></header>
<main>
<div class="title"><div><h1>Boarding counts</h1><p class="sub">Manual observations at Maple Corner and Library Square.</p></div><button class="action" id="add"><span aria-hidden="true">+</span>Add session</button></div>
<div class="filters" role="group" aria-label="Inclusive date range"><strong>Date range</strong><label>From<input id="from" type="date"></label><label>Through<input id="through" type="date"></label><button class="clear" id="clear">Clear dates</button></div>
<p id="warning" class="error" role="alert"></p>
<section><div class="sectionhead"><h2>Stop comparison</h2><span id="scope" class="scope" aria-live="polite"></span></div><div id="cards" class="cards"></div>
<details><summary>How the rates are calculated</summary><p>For each stop, add up the boardings, minutes and buses in the selected dates. Divide total boardings by total observed hours for the hourly rate, or by total buses for the per-bus rate. Every observed minute counts, including time spent waiting when no buses arrive. A dash means the rate has no denominator.</p></details></section>
<section><div class="recordhead"><h2>Session log</h2></div><div class="tablewrap" tabindex="0" role="region" aria-label="Observation sessions"><table><thead><tr><th>Date</th><th>Stop</th><th>Minutes observed</th><th>Boardings</th><th>Buses</th><th>Boardings / bus</th></tr></thead><tbody id="log"></tbody></table></div><p class="foot">— &nbsp;No buses observed. The per-bus rate is undefined.</p></section>
<p id="status" class="message" role="status"></p><p id="storage" class="storage" role="alert"></p>
<footer>The six starting sessions are fictional. Added sessions are stored in this browser.</footer>
</main>
<dialog id="entry" aria-labelledby="entrytitle"><form id="form"><h2 id="entrytitle">Add session</h2><label>Date<input name="date" type="date" required min="0001-01-01" max="9999-12-31"></label><label>Stop<select name="stop"><option>Maple Corner</option><option>Library Square</option></select></label><label>Minutes observed<input name="minutes" type="number" min="1" step="1" required></label><label>Boardings<input name="boardings" type="number" min="0" step="1" required></label><label>Buses<input name="buses" type="number" min="0" step="1" required></label><div class="actions"><button id="cancel" type="button">Cancel</button><button class="action">Save session</button></div></form></dialog>
<script>
'"'use strict';
const stops = ['Maple Corner','Library Square'];
const seed = [
  ['2026-06-01',0,30,18,3], ['2026-06-01',1,45,36,4],
  ['2026-06-03',0,45,24,4], ['2026-06-03',1,30,20,3],
  ['2026-06-08',0,60,33,6], ['2026-06-08',1,30,0,0]
].map(([date,stop,minutes,boardings,buses]) => ({date,stop:stops[stop],minutes,boardings,buses}));
const byId = id => document.getElementById(id);
const prefix = 'stop-ledger.session.v1.';
const additions = new Map();
function valid(s) {
  if ("'!s || !/''^'"\\d{4}-\\d{2}-\\d{2}"'$/.test(s.date) || !stops.includes(s.stop)) return false;
  const day = new Date(s.date+'"'T00:00:00Z');
  return Number.isFinite(+day) && day.toISOString().slice(0,10) === s.date &&
    [s.minutes,s.boardings,s.buses].every(n => Number.isSafeInteger(n) && n >= 0) &&
    s.minutes > 0 && (s.buses > 0 || s.boardings === 0);
}
function readSaved() {
  try {
    for (const key of Object.keys(localStorage).filter(k => k.startsWith(prefix))) {
      try {
        const s = JSON.parse(localStorage.getItem(key));
        if ("'!valid(s)) throw Error();
        additions.set(key,s);
      } catch { byId('"'storage').textContent = 'A saved session could not be read.'; }
    }
  } catch { byId('storage').textContent = 'Browser storage is unavailable. Entries last only while this page is open.'; }
}
const rate = (n,d) => d ? (n/d).toFixed(1) : '—';
const dateFormat = new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
function render() {
  const from = byId('from').value, end = byId('through').value;
  const reversed = from && end && from > end;
  byId('warning').textContent = reversed ? 'Choose an end date on or after the start date.' : '';
  const rows = [...seed,...additions.values()].filter(s => ("'!from || s.date >= from) && (!end || s.date <= end))
    .sort((a,b) => b.date.localeCompare(a.date) || stops.indexOf(a.stop)-stops.indexOf(b.stop));
  byId('"'scope').textContent = (from || end ? 'Filtered dates' : 'All dates')+' · '+rows.length+' session'+(rows.length === 1 ? '' : 's');
  byId('cards').innerHTML = stops.map((stop,i) => {
    const group = rows.filter(s => s.stop === stop);
    const sum = key => group.reduce((a,s) => a+s[key],0);
    const m=sum('minutes'), b=sum('boardings'), v=sum('buses');
    return '<article class=\"card '+(i?'library':'')+'\"><div class=\"cardhead\"><span class=\"marker\" aria-hidden=\"true\">'+stop[0]+'</span><h3>'+stop+'</h3></div><div class=\"stats\"><div class=\"stat\"><b>'+rate(b*60,m)+'</b><small>Boardings / observed hour</small></div><div class=\"stat\"><b>'+rate(b,v)+'</b><small>Boardings / bus</small></div></div><div class=\"totals\">'+(group.length ? b+' boardings · '+m+' min · '+v+' buses' : 'No sessions in range')+'</div></article>';
  }).join('');
  byId('log').innerHTML = rows.map(s => '<tr><td>'+dateFormat.format(new Date(s.date+'T00:00:00Z'))+'</td><td class=\"stop\"><span class=\"dot '+(s.stop===stops[1]?'library':'')+'\"></span>'+s.stop+'</td><td>'+s.minutes+'</td><td>'+s.boardings+'</td><td>'+s.buses+'</td><td>'+rate(s.boardings,s.buses)+'</td></tr>').join('') || '<tr><td class=\"empty\" colspan=\"6\">No sessions in this date range.</td></tr>';
}
function refreshFilters(){byId('status').textContent=''; render();}
for(const id of ['from','through']) byId(id).oninput = refreshFilters;
byId('clear').onclick = () => {byId('from').value=byId('through').value=''; refreshFilters();};
const form = byId('form'), fields = form.elements, entry = byId('entry');
byId('add').onclick = () => {
  form.reset();
  const now = new Date();
  fields.date.value = new Date(+now-now.getTimezoneOffset()*60000).toISOString().slice(0,10);
  fields.buses.setCustomValidity('');
  entry.showModal();
};
byId('cancel').onclick = () => entry.close();
form.oninput = () => fields.buses.setCustomValidity('');
form.onsubmit = event => {
  event.preventDefault();
  const s = {date:fields.date.value, stop:fields.stop.value};
  for(const key of ['minutes','boardings','buses']) {
    s[key]=fields[key].valueAsNumber;
    if("'!Number.isSafeInteger(s[key])) {
      fields[key].setCustomValidity('"'Enter a whole number within the supported range.');
      fields[key].reportValidity();
      fields[key].setCustomValidity('');
      return;
    }
  }
  if("'!valid(s)){
    fields.buses.setCustomValidity('"'Enter at least one bus when boardings are recorded.');
    fields.buses.reportValidity(); return;
  }
  const key = prefix+Date.now()+'-'+Math.random().toString(36).slice(2);
  additions.set(key,s);
  let message = 'Session saved.';
  try {localStorage.setItem(key,JSON.stringify(s));}
  catch {message = 'Session added for this visit only. Browser storage is unavailable.';}
  if ((byId('from').value && s.date < byId('from').value) || (byId('through').value && s.date > byId('through').value))
    message += ' Clear the date range to see this session.';
  entry.close(); render(); byId('status').textContent=message;
};
window.addEventListener('storage',() => {readSaved(); render();});
readSaved(); render();
</script>
</body>
</html>
